2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives the owner's {@code membershipPoints} and the numeric {@code membershipLevel} mapped from
7	 * them.
8	 *
9	 * <p>Points start at 0 and accumulate: 2 when the owner has an email address on record, 1 when the
10	 * owner had no namesakes at creation ({@code namesakeCount} is 0), 2 for a household of 3 or more
11	 * members, and 3 when the owner's tenure exceeds one elapsed fiscal year. The points then map to a
12	 * level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Because a newly created owner
13	 * has zero tenure, the +3 tenure award is out of reach at creation, so a new owner scores at most 5
14	 * points (2 email + 1 namesake + 2 household) and never exceeds level 3.
15	 */
16	public final class Membership {
17	
18	    /** Household size, in members, at or above which the household points are granted. */
19	    private static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;
20	
21	    /** Tenure, in elapsed fiscal years, that must be exceeded before the tenure points are granted. */
22	    private static final long TENURE_FISCAL_YEARS_FOR_POINTS = 1;
23	
24	    private Membership() {
25	    }
26	
27	    /** The owner's membership points, from 0 upwards. */
28	    public static int pointsOf(Owner owner) {
29	        return pointsOf(owner, owner.getHouseholdMemberCount());
30	    }
31	
32	    /**
33	     * The owner's membership points as if its household had {@code householdMemberCount} members —
34	     * every factor except the household award is read from the owner as stored; the household award
35	     * (+2 for {@value #HOUSEHOLD_SIZE_FOR_POINTS} or more members) is granted from the supplied count.
36	     * Used to score existing household members in the household as it currently stands rather than as
37	     * it stood when each was created.
38	     */
39	    public static int pointsOf(Owner owner, Integer householdMemberCount) {
40	        int points = 0;
41	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
42	            points += 2;
43	        }
44	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
45	            points += 1;
46	        }
47	        if (householdMemberCount != null && householdMemberCount >= HOUSEHOLD_SIZE_FOR_POINTS) {
48	            points += 2;
49	        }
50	        if (FiscalYears.elapsedSinceRegistration(owner) > TENURE_FISCAL_YEARS_FOR_POINTS) {
51	            points += 3;
52	        }
53	        return points;
54	    }
55	
56	    /** The owner's numeric membership level, mapped from {@link #pointsOf(Owner)}: 1 for 0-1
57	     * points, 2 for 2-3, 3 for 4-5, 4 for 6 or more. */
58	    public static int levelOf(Owner owner) {
59	        return levelForPoints(pointsOf(owner));
60	    }
61	
62	    /** The numeric membership level the owner would hold in a household of the given size (see
63	     * {@link #pointsOf(Owner, Integer)}). */
64	    public static int levelOf(Owner owner, Integer householdMemberCount) {
65	        return levelForPoints(pointsOf(owner, householdMemberCount));
66	    }
67	
68	    /** Map membership points to a level: 1 for 0-1, 2 for 2-3, 3 for 4-5, 4 for 6 or more. */
69	    public static int levelForPoints(int points) {
70	        if (points >= 6) {
71	            return 4;
72	        }
73	        if (points >= 4) {
74	            return 3;
75	        }
76	        if (points >= 2) {
77	            return 2;
78	        }
79	        return 1;
80	    }
81	}
