3	/**
4	 * Derives a single Luhn check digit over the digits contained in a value.
5	 *
6	 * <p>Used for the owner's {@code checkDigit}, computed over the digits of its
7	 * {@code customerCode}. Non-digit characters are ignored, so the region prefix and separator in a
8	 * code such as {@code 'NSW-1A2B3C4D'} do not contribute; the rightmost digit is doubled first per the
9	 * standard Luhn algorithm.
10	 */
11	public final class CheckDigits {
12	
13	    private CheckDigits() {
14	    }
15	
16	    /** The Luhn check digit (0-9) over the digits contained in {@code value}; 0 when null. */
17	    public static int luhnOf(String value) {
18	        if (value == null) {
19	            return 0;
20	        }
21	        int sum = 0;
22	        boolean dbl = true;
23	        for (int i = value.length() - 1; i >= 0; i--) {
24	            char c = value.charAt(i);
25	            if (c < '0' || c > '9') {
26	                continue;
27	            }
28	            int d = c - '0';
29	            if (dbl) {
30	                d *= 2;
31	                if (d > 9) {
32	                    d -= 9;
33	                }
34	            }
35	            sum += d;
36	            dbl = !dbl;
37	        }
38	        return (10 - (sum % 10)) % 10;
39	    }
40	}
