3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives fiscal-year values. The fiscal year starts on 1 July, so a date on or after 1 July belongs
9	 * to the next calendar year's fiscal year (e.g. 2025-07-01 through 2026-06-30 is fiscal year 2026).
10	 *
11	 * <p>The owner's stored {@code registrationDate} has already been rolled forward to a business day
12	 * (see {@link BusinessDay}), so values derived here are on the business-day-adjusted basis.
13	 */
14	public final class FiscalYears {
15	
16	    /** Month (1-based) on which the fiscal year starts. */
17	    private static final int FISCAL_YEAR_START_MONTH = 7;
18	
19	    private FiscalYears() {
20	    }
21	
22	    /** The four-digit fiscal year that {@code date} falls in. */
23	    public static int yearOf(LocalDate date) {
24	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
25	    }
26	
27	    /**
28	     * The owner's fiscal year label, formatted {@code 'FY<YY>'} where {@code YY} is the last two
29	     * digits of the fiscal year the {@code registrationDate} falls in; {@code null} when no date is
30	     * on record.
31	     */
32	    public static String labelOf(Owner owner) {
33	        LocalDate registrationDate = owner.getRegistrationDate();
34	        if (registrationDate == null) {
35	            return null;
36	        }
37	        int yy = Math.floorMod(yearOf(registrationDate), 100);
38	        return String.format("FY%02d", yy);
39	    }
40	
41	    /** Fiscal years elapsed since the owner's registration date; 0 when no date is on record. */
42	    public static long elapsedSinceRegistration(Owner owner) {
43	        LocalDate registrationDate = owner.getRegistrationDate();
44	        if (registrationDate == null) {
45	            return 0;
46	        }
47	        return (long) yearOf(LocalDate.now()) - yearOf(registrationDate);
48	    }
49	}
