3	import java.util.Map;
4	
5	/**
6	 * Fixed region-to-postcode-range lookup used to validate an owner's optional 4-digit
7	 * 'postcode' against the region derived from its city (see {@link Localities}). The ranges
8	 * are pinned and inclusive: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A city whose region
9	 * is not in the table (locality "UNKNOWN") accepts any 4-digit postcode.
10	 */
11	public final class Postcodes {
12	
13	    /** Region -> inclusive 4-digit postcode range {low, high}. */
14	    private static final Map<String, int[]> REGION_RANGE = Map.of(
15	            "NSW", new int[] {2000, 2099},
16	            "VIC", new int[] {3000, 3099},
17	            "QLD", new int[] {4000, 4099});
18	
19	    private Postcodes() {
20	    }
21	
22	    /**
23	     * The region whose inclusive range contains {@code postcode}, or {@code null} when the
24	     * postcode is absent, cannot be parsed as an integer, or falls in no known range. Used to
25	     * derive the locality from the postcode in preference to the city (see {@link Localities}).
26	     */
27	    public static String regionOf(String postcode) {
28	        if (postcode == null) {
29	            return null;
30	        }
31	        int value;
32	        try {
33	            value = Integer.parseInt(postcode);
34	        }
35	        catch (NumberFormatException ex) {
36	            return null;
37	        }
38	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
39	            int[] range = entry.getValue();
40	            if (value >= range[0] && value <= range[1]) {
41	                return entry.getKey();
42	            }
43	        }
44	        return null;
45	    }
46	
47	    /**
48	     * Whether {@code postcode} is acceptable for {@code city}. A null postcode is acceptable
49	     * (the field is optional). Assumes the 4-digit format has already been validated; a value
50	     * that cannot be parsed as an integer is treated as invalid. When the city's region has no
51	     * known range every 4-digit postcode is accepted.
52	     */
53	    public static boolean isValidForCity(String postcode, String city) {
54	        if (postcode == null) {
55	            return true;
56	        }
57	        int[] range = REGION_RANGE.get(Localities.of(city));
58	        if (range == null) {
59	            return true;
60	        }
61	        int value;
62	        try {
63	            value = Integer.parseInt(postcode);
64	        }
65	        catch (NumberFormatException ex) {
66	            return false;
67	        }
68	        return value >= range[0] && value <= range[1];
69	    }
70	}
