3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	import org.springframework.samples.petclinic.rest.function.common.IdentityKeys;
9	
10	/**
11	 * The duplicate-detection step of {@code POST /api/owners}. Runs after {@link ValidateOwnerFields}
12	 * has normalized the telephone and email (and after {@link RejectDisposableEmailDomain} has applied
13	 * the email-domain blocklist). It rejects the create with a 409 Conflict when the request's whole
14	 * {@code identityKey} — the {@code SHA-256} of
15	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, see {@link IdentityKeys} —
16	 * equals a live owner's.
17	 *
18	 * <p>Duplicate detection is the single identity key: there is no separate household-duplicate block.
19	 * Because the telephone is part of the key, two owners with the same last name and postcode but
20	 * different telephones have different keys, so the second is created (and later flagged a possible
21	 * duplicate by {@link AssignPossibleDuplicate}) rather than rejected. Soft-deleted owners are ignored
22	 * — a retired identity cannot block a create.
23	 */
24	public class RejectDuplicateIdentity {
25	
26	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws DuplicateIdentityException {
28	        String identityKey = IdentityKeys.of(request.getTelephone(), request.getEmail(),
29	                request.getLastName());
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (existing.isDeleted()) {
32	                // A soft-deleted owner is no longer a live identity; it cannot block a create.
33	                continue;
34	            }
35	            if (identityKey.equals(IdentityKeys.of(existing))) {
36	                throw new DuplicateIdentityException(identityKey);
37	            }
38	        }
39	    }
40	}
