2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.function.common.IdentityKeys;
8	import org.springframework.samples.petclinic.rest.function.common.Soundex;
9	
10	/**
11	 * Soft-match step of {@code POST /api/owners}. By the time it runs the request has already passed
12	 * {@link RejectDuplicateIdentity}, so it is <em>not</em> a hard duplicate (no live owner shares its
13	 * {@code identityKey}); this step then looks for a weaker signal that it might be one anyway: an
14	 * existing owner whose last name has the same {@link Soundex} code and whose postcode matches, while
15	 * its {@code identityKey} differs. Such an owner is still created, but is flagged with
16	 * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to the matching owner's id (the
17	 * lowest id when several match). When nothing matches, {@code possibleDuplicate} is set to
18	 * {@code false} and no id is recorded.
19	 *
20	 * <p>Because the telephone is part of the identity key, two owners with the same last name and
21	 * postcode but different telephones are exactly this soft match — no longer a hard household
22	 * duplicate. A <em>declared</em> household member — one created with {@code sharesHousehold: true} —
23	 * is never flagged: sharing a same-household owner's last name and postcode is expected, not a
24	 * suspected duplicate.
25	 *
26	 * <p>Runs after {@link BuildOwner} so the owner carries its normalized lastName, postcode and
27	 * telephone, and before {@link SaveOwner} so the comparison sees only owners that existed before this
28	 * create — the new owner is not yet persisted and so never matches itself. {@code @Val} yields the
29	 * built owner, mutated in place and persisted by the save step.
30	 */
31	public class AssignPossibleDuplicate {
32	
33	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
34	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
35	            // A declared household member is not a suspected duplicate.
36	            owner.setPossibleDuplicate(false);
37	            owner.setPossibleDuplicateOf(null);
38	            return;
39	        }
40	        String soundex = Soundex.of(owner.getLastName());
41	        String postcode = normalizePostcode(owner.getPostcode());
42	        String identityKey = IdentityKeys.of(owner);
43	        Integer match = null;
44	        if (postcode != null) {
45	            for (Owner existing : ownerRepository.findAll()) {
46	                if (existing.isDeleted() || existing.getId() == null) {
47	                    // A soft-deleted owner is not a live duplicate to flag against.
48	                    continue;
49	                }
50	                if (soundex.equals(Soundex.of(existing.getLastName()))
51	                        && postcode.equals(normalizePostcode(existing.getPostcode()))
52	                        && !identityKey.equals(IdentityKeys.of(existing))
53	                        && (match == null || existing.getId() < match)) {
54	                    match = existing.getId();
55	                }
56	            }
57	        }
58	        owner.setPossibleDuplicate(match != null);
59	        owner.setPossibleDuplicateOf(match);
60	    }
61	
62	    /** Trim the postcode, treating a null or blank value as absent (no possible-duplicate match). */
63	    private static String normalizePostcode(String value) {
64	        if (value == null) {
65	            return null;
66	        }
67	        String trimmed = value.trim();
68	        return trimmed.isEmpty() ? null : trimmed;
69	    }
70	}
